INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('gate-puzzler','advanced','Prove that NAND is functionally complete',ARRAY['NAND can build NOT, AND, OR','NAND is fast','NAND uses few transistors','NAND is cheap'],0,'NOT: NAND(A,A); AND: NOT(NAND(A,B)); OR: NAND(NOT A, NOT B).',20),
('gate-puzzler','advanced','Implement XOR using only NAND gates. How many NAND gates are needed?',ARRAY['4','2','3','5'],0,'XOR = NAND(A,NAND(A,B)) XOR NAND(B,NAND(A,B)) — 4 NANDs.',20),
('gate-puzzler','advanced','Implement a 2:1 MUX using only NAND. How many NAND gates?',ARRAY['4','3','2','5'],0,'MUX: Y = AS + B S'' needs 4 NAND gates.',20),
('gate-puzzler','advanced','What is the minimal SOP for F(A,B,C) = Σm(0,1,2,5,6,7)?',ARRAY['A''C'' + AB + BC'' + B''C','A + B + C','ABC + A''B''C''','A''B'' + AB'],0,'K-map minimization yields A''C'' + AB + BC'' + B''C.',20),
('gate-puzzler','advanced','What is the minimal POS for F(A,B,C) = Σm(0,1,2,5,6,7)?',ARRAY['(A+B''+C)(A''+B+C'')','(A+B+C)(A+B''+C'')','(A''+B''+C)(A+B+C)','(A+B)(B+C)'],0,'Group zeros in K-map for POS form.',20),
('gate-puzzler','advanced','Design a 4-bit carry-lookahead adder. What is C4 in terms of G and P?',ARRAY['G3 + P3·G2 + P3·P2·G1 + P3·P2·P1·G0','C0 + G3','P3·G3','G3·P2'],0,'CLA carry: C4 = G3 + P3G2 + P3P2G1 + P3P2P1G0.',20),
('gate-puzzler','advanced','What is the group generate G for a 4-bit CLA block?',ARRAY['G3 + P3G2 + P3P2G1 + P3P2P1G0','G0+G1+G2+G3','P0P1P2P3','G3P3'],0,'Group generate combines individual generates.',20),
('gate-puzzler','advanced','What is the group propagate P for a 4-bit CLA block?',ARRAY['P3·P2·P1·P0','P0+P1+P2+P3','G0G1G2G3','P3+P0'],0,'Group propagate = AND of all individual propagates.',20),
('gate-puzzler','advanced','How many gate delays does a 4-bit CLA adder have?',ARRAY['2 levels of logic','4 levels','8 levels','16 levels'],0,'CLA carry is computed in 2 gate levels.',20),
('gate-puzzler','advanced','What is the Quine-McCluskey method used for?',ARRAY['Minimizing Boolean functions','Designing counters','Testing circuits','Simulating gates'],0,'Tabular method for Boolean minimization.',20),
('gate-puzzler','advanced','What is a prime implicant?',ARRAY['An implicant that cannot be covered by a larger one','The largest minterm','The smallest maxterm','Any implicant'],0,'Prime implicants are maximal groups in K-map.',20),
('gate-puzzler','advanced','What is an essential prime implicant?',ARRAY['A prime implicant covering a minterm no other PI covers','Any prime implicant','The largest PI','The smallest PI'],0,'Essential PIs must be included in the minimal form.',20),
('gate-puzzler','advanced','How many prime implicants can a 4-variable function have at most?',ARRAY['8','4','16','32'],0,'Maximum 2^(n-1) = 8 for n=4.',20),
('gate-puzzler','advanced','What is a don''t-care condition in K-maps?',ARRAY['A combination that can be 0 or 1','An error condition','A forbidden state','A reset state'],0,'Don''t-cares help simplify logic.',20),
('gate-puzzler','advanced','What are Petrick''s method and iterated consensus used for?',ARRAY['Finding minimal covers of prime implicants','Designing adders','Testing circuits','Clock generation'],0,'Petrick''s method finds all minimal SOP covers.',20),
('gate-puzzler','advanced','Design a 3:8 decoder using two 2:4 decoders. What additional gate is needed?',ARRAY['1 AND gate for enable','1 OR gate','1 NOT gate','1 XOR gate'],0,'The MSB selects which 2:4 decoder is active.',20),
('gate-puzzler','advanced','How many 2:4 decoders are needed to build a 4:16 decoder?',ARRAY['5','2','3','4'],0,'Four for the outputs plus one for enable selection.',20),
('gate-puzzler','advanced','Implement F = A''B'' + AB using a 2:1 MUX. What connects to the select line?',ARRAY['A','B','A''','Ground'],0,'With A on select: I0 = B'', I1 = B gives F = A''B'' + AB.',20),
('gate-puzzler','advanced','How many 4:1 MUXes are needed to implement a 3-variable function?',ARRAY['1','2','3','4'],0,'One 4:1 MUX with 2 variables on select lines suffices.',20),
('gate-puzzler','advanced','What is the Shannon expansion theorem?',ARRAY['F = S·F(1) + S''·F(0)','F = A + B','F = AB','F = A⊕B'],0,'Shannon expansion decomposes functions around a variable.',20),
('gate-puzzler','advanced','What is a transmission gate?',ARRAY['Parallel NMOS and PMOS passing signals in both directions','A series switch','A buffer','An inverter'],0,'TG = NMOS || PMOS, bidirectional switch.',20),
('gate-puzzler','advanced','How do you build a D latch using transmission gates?',ARRAY['2 TGs + inverter feedback','4 NAND gates','6 NOR gates','1 multiplexer'],0,'TG-based latches are compact and fast.',20),
('gate-puzzler','advanced','What is the difference between static and dynamic CMOS logic?',ARRAY['Static uses pull-up/pull-down networks; dynamic uses clocks','Static is faster','Dynamic uses less area','No difference'],0,'Dynamic logic uses clocked evaluation; static is always on.',20),
('gate-puzzler','advanced','What is domino logic?',ARRAY['Dynamic CMOS with a static inverter per stage','Static CMOS variant','Clocked latch','Bipolar logic'],0,'Domino cascades dynamic stages with inverters.',20),
('gate-puzzler','advanced','What is the main advantage of domino logic?',ARRAY['High speed and compact area','Low power','High noise margin','Easy to design'],0,'Domino logic is faster and smaller than static CMOS.',20),
('gate-puzzler','advanced','What is the main disadvantage of domino logic?',ARRAY['Charge leakage and clock overhead','Slow speed','Large area','Low noise margin'],0,'Dynamic nodes leak charge between clock phases.',20),
('gate-puzzler','advanced','What is NORA logic?',ARRAY['No Race Conditions dynamic logic','Static CMOS','Bipolar logic','ECL logic'],0,'NORA uses alternating n-blocks and p-blocks to avoid races.',20),
('gate-puzzler','advanced','What is the difference between ripple-carry and carry-skip adders?',ARRAY['Carry-skip bypasses carry through groups','Carry-skip is slower','Ripple is faster','No difference'],0,'Carry-skip adds bypass logic for faster carry propagation.',20),
('gate-puzzler','advanced','What is a carry-select adder?',ARRAY['Precomputes both carry=0 and carry=1, selects later','Adds in parallel','Uses CLA only','Is a multiplier'],0,'CSA precomputes both cases and muxes the result.',20),
('gate-puzzler','advanced','What is a Wallace tree multiplier?',ARRAY['Parallel multiplier using carry-save adders','Sequential multiplier','Shift-add multiplier','Array multiplier'],0,'Wallace tree compresses partial products in parallel.',20),
('gate-puzzler','advanced','What is a Booth multiplier?',ARRAY['Encodes multipliers to reduce partial products','Uses Wallace tree','Is an adder','Is a divider'],0,'Booth encoding reduces the number of partial products.',20),
('gate-puzzler','advanced','What is the advantage of radix-4 Booth encoding?',ARRAY['Halves the number of partial products','Doubles speed','Reduces power','Increases area'],0,'Radix-4 Booth processes 2 bits at a time.',20),
('gate-puzzler','advanced','What is a barrel shifter?',ARRAY['Combinational shifter that shifts any amount in one cycle','Sequential shifter','Single-bit shifter','Rotate-only circuit'],0,'Barrel shifters use a crossbar of multiplexers.',20),
('gate-puzzler','advanced','How many muxes does an 8-bit barrel shifter use?',ARRAY['8','4','16','2'],0,'One 8:1 MUX per output bit = 8 muxes.',20),
('gate-puzzler','advanced','What is an ALU?',ARRAY['Arithmetic Logic Unit performing multiple operations','Adder only','Multiplier','Comparator'],0,'ALU performs arithmetic and logic operations.',20),
('gate-puzzler','advanced','How many select lines does a 16-operation ALU need?',ARRAY['4','3','2','5'],0,'2^4 = 16 operations.',20),
('gate-puzzler','advanced','What is the difference between structural and behavioral HDL?',ARRAY['Structural describes gate-level; behavioral describes function','Structural is faster','Behavioral uses more area','No difference'],0,'Structural = netlist; behavioral = algorithm.',20),
('gate-puzzler','advanced','What is gate-level netlist?',ARRAY['List of gates and their interconnections','RTL code','Test bench','Timing report'],0,'Gate-level netlist is post-synthesis.',20),
('gate-puzzler','advanced','What is the difference between blocking and non-blocking assignments in Verilog?',ARRAY['Blocking (=) executes in order; non-blocking (<=) schedules simultaneously','Blocking is faster','Non-blocking is slower','No difference'],0,'Use non-blocking for sequential, blocking for combinational.',20),
('gate-puzzler','advanced','What is a testbench in HDL?',ARRAY['Code that applies stimulus and checks outputs','Synthesis tool','Timing analyzer','Place and route tool'],0,'Testbenches verify design correctness.',20),
('gate-puzzler','advanced','What is assertion-based verification?',ARRAY['Checking design properties at runtime','Code coverage','Gate-level simulation','Power analysis'],0,'Assertions check temporal properties automatically.',20),
('gate-puzzler','advanced','What is formal verification?',ARRAY['Mathematically proves design equivalence','Simulation-based check','Visual inspection','Manual review'],0,'Formal verification proves two designs are equivalent.',20),
('gate-puzzler','advanced','What is STA?',ARRAY['Static Timing Analysis','Sequential Timing Analyzer','Standard Test Architecture','Static Test Analyzer'],0,'STA checks all timing paths without simulation.',20),
('gate-puzzler','advanced','What is the critical path in a circuit?',ARRAY['Longest delay path limiting clock frequency','Shortest path','Power supply path','Reset path'],0,'Critical path determines max operating frequency.',20),
('gate-puzzler','advanced','What is slack in timing analysis?',ARRAY['Difference between required and actual arrival time','Extra gates','Unused inputs','Clock period'],0,'Positive slack = meets timing; negative = violates.',20),
('gate-puzzler','advanced','What is clock skew?',ARRAY['Difference in clock arrival times at different FFs','Clock frequency','Clock duty cycle','Clock jitter'],0,'Skew can help or hurt timing depending on direction.',20),
('gate-puzzler','advanced','What is useful skew?',ARRAY['Intentionally delaying clock to relax setup constraints','Accidental skew','Clock jitter','Clock drift'],0,'Useful skew borrows time from next stage.',20),
('gate-puzzler','advanced','What is power dissipation in CMOS?',ARRAY['Dynamic (switching) + static (leakage) power','Dynamic only','Static only','Short-circuit only'],0,'P = P_dynamic + P_leakage + P_short_circuit.',20),
('gate-puzzler','advanced','What is the formula for dynamic power?',ARRAY['P = CV²f','P = IR','P = V²/R','P = VI'],0,'Dynamic power = capacitance × voltage² × frequency.',20),
('gate-puzzler','advanced','What is clock gating for?',ARRAY['Reducing dynamic power by disabling clocks to idle blocks','Increasing speed','Adding latency','Improving noise margin'],0,'Clock gating saves power by stopping unnecessary switching.',20);